function solve(intervals) {
  const a = intervals.map((x) => x.slice()).sort((x, y) => x[0] - y[0]);
  const out = [];
  for (const [s, e] of a) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}
